// State machine controller
const input = $input.first().json;
const phone = input.phoneNumber;
const message = input.messageBody;
const staticData = $getWorkflowStaticData('global');

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[phone]) {
  staticData.sessions[phone] = {
    state: 'new',
    data: {},
    history: [],
    lastActivity: Date.now()
  };
}

const session = staticData.sessions[phone];
const currentState = input.currentState || session.state || 'new';

return [{
  json: {
    ...input,
    currentState,
    sessionData: session.data || {},
    conversationHistory: input.conversationHistory || session.history || []
  }
}];

// State: NEW - Send greeting and ask for name
const input = $input.first().json;
const phone = input.phoneNumber;
const staticData = $getWorkflowStaticData('global');

const replyText = 'أهلاً وسهلاً بيك في Med Africa! 🌍\nأنا هنا باش نعاونك.\nعافاك، شنو سميتك الكاملة؟';

// Update state
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[phone]) staticData.sessions[phone] = { data: {}, history: [] };
staticData.sessions[phone].state = 'waiting_name';
staticData.sessions[phone].lastActivity = Date.now();
staticData.sessions[phone].history = [
  ...(staticData.sessions[phone].history || []),
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
];

return [{ json: { ...input, replyText, nextState: 'waiting_name' } }];

// State: WAITING_NAME - Save name, ask for lastname
const input = $input.first().json;
const phone = input.phoneNumber;
const name = input.messageBody.trim();
const staticData = $getWorkflowStaticData('global');

// Save name
staticData.sessions[phone].data.firstName = name;
staticData.sessions[phone].state = 'waiting_lastname';
staticData.sessions[phone].lastActivity = Date.now();

const replyText = `شكرا ${name}! 👍\nعافاك، شنو النسب ديالك (اللقب العائلي)؟`;

staticData.sessions[phone].history.push(
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
);

return [{ json: { ...input, replyText, nextState: 'waiting_lastname' } }];

// State: WAITING_LASTNAME - Save lastname, ask for city
const input = $input.first().json;
const phone = input.phoneNumber;
const lastname = input.messageBody.trim();
const staticData = $getWorkflowStaticData('global');

// Save lastname
staticData.sessions[phone].data.lastName = lastname;
staticData.sessions[phone].state = 'waiting_city';
staticData.sessions[phone].lastActivity = Date.now();

const replyText = 'مزيان! 🏙️\nمن أي مدينة نتا/نتي؟';

staticData.sessions[phone].history.push(
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
);

return [{ json: { ...input, replyText, nextState: 'waiting_city' } }];

// State: WAITING_CITY - Save city, ask for tracking number
const input = $input.first().json;
const phone = input.phoneNumber;
const city = input.messageBody.trim();
const staticData = $getWorkflowStaticData('global');

// Save city
staticData.sessions[phone].data.city = city;
staticData.sessions[phone].state = 'waiting_tracking';
staticData.sessions[phone].lastActivity = Date.now();

const replyText = 'تمام! 📦\nعافاك عطيني رقم التتبع ديالك (numéro de suivi):';

staticData.sessions[phone].history.push(
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
);

return [{ json: { ...input, replyText, nextState: 'waiting_tracking' } }];

// State: WAITING_TRACKING - Save tracking, ask for issue
const input = $input.first().json;
const phone = input.phoneNumber;
const tracking = input.messageBody.trim();
const staticData = $getWorkflowStaticData('global');

// Save tracking number
staticData.sessions[phone].data.trackingNumber = tracking;
staticData.sessions[phone].state = 'classifying';
staticData.sessions[phone].lastActivity = Date.now();

const replyText = 'شكرا! 🙏\nدابا عافاك قولي: شنو المشكل أو الاستفسار ديالك؟';

staticData.sessions[phone].history.push(
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
);

return [{ json: { ...input, replyText, nextState: 'classifying' } }];

// Process AI classification response
const input = $input.first().json;
const phone = input.phoneNumber || $('Load Session State').first().json.phoneNumber;
const staticData = $getWorkflowStaticData('global');
const aiResponse = input.aiResponse || input;

// Parse AI response
let replyText = aiResponse.reply || aiResponse.reply_text || '';
let detectedType = aiResponse.type || 'استفسار';
let category = aiResponse.category || 'عام';
let priority = aiResponse.priority || 'عادي';
let summary = aiResponse.summary || '';
let dataComplete = aiResponse.data_complete || false;

const session = staticData.sessions[phone];

if (dataComplete) {
  // Move to completed state
  session.state = 'completed';
  session.data.type = detectedType;
  session.data.category = category;
  session.data.priority = priority;
  session.data.summary = summary;
  session.data.description = $('Load Session State').first().json.messageBody;
} else if (detectedType === 'شكوى') {
  session.state = 'complaint_flow';
} else {
  session.state = 'inquiry_flow';
}

session.lastActivity = Date.now();
session.history.push(
  { role: 'assistant', content: replyText, timestamp: Math.floor(Date.now()/1000).toString() }
);

return [{
  json: {
    phoneNumber: phone,
    replyText,
    detectedType,
    category,
    priority,
    summary,
    dataComplete,
    nextState: session.state,
    sessionData: session.data
  }
}];

// Handle complaint/inquiry sub-flow — continue conversation with AI
const input = $input.first().json;
const phone = input.phoneNumber;
const staticData = $getWorkflowStaticData('global');
const session = staticData.sessions[phone];

// For sub-flows, we continue calling AI until data_complete = true
return [{ json: { ...input } }];

// Clean up session after completion
const phone = $input.first().json.phoneNumber;
const staticData = $getWorkflowStaticData('global');

// Mark session as completed but keep for reference
if (staticData.sessions && staticData.sessions[phone]) {
  staticData.sessions[phone].state = 'completed';
  staticData.sessions[phone].completedAt = Date.now();
}

const ticketId = $input.first().json.ticketId || 'N/A';
const replyText = $input.first().json.replyText;

return [{ json: { phoneNumber: phone, replyText, ticketId } }];

// Session cleanup cron - remove expired sessions
// This can be triggered periodically
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const SESSION_TIMEOUT = 30 * 60 * 1000;

if (staticData.sessions) {
  const phones = Object.keys(staticData.sessions);
  let cleaned = 0;
  for (const phone of phones) {
    const session = staticData.sessions[phone];
    if (session.state === 'completed' || (now - session.lastActivity) > SESSION_TIMEOUT) {
      delete staticData.sessions[phone];
      cleaned++;
    }
  }
  return [{ json: { cleaned, remaining: Object.keys(staticData.sessions).length } }];
}

return [{ json: { cleaned: 0, remaining: 0 } }];
